"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[815],{815:function(a){a.exports=JSON.parse('{"name":"Patrick Goodwin","menu":{"home":"Gida","about":"Akai na","portfolio":"Fayil","projects":"Ayyukan Yanar Gizo","tiger":"Harshen Tiger","portfolio_translator":"Mai Fassarar Fayil","formatter":"JSON & YAML Formatter","contact":"Tuntube Ni"},"home":{"title":"Babban Injiniya Cikakkun Tari | Samfura & Tsarin","animated":{"first":"Babban Injiniya Cikakkun Tari","second":"Sistoci & Gine-ginen Gine-gine","third":"Injiniyan Samfuran SaaS","fourth":"Amintaccen Software, Sakamakon Kasuwanci"},"footer":"An fassara gidan yanar gizon yanzu kuma ana samunsa cikin harsuna 100+!","descriptionA":"Babban injiniya mai cikakken tari tare da shekaru 6+ na gwaninta yana \u0257aukar samfura daga bu\u0199atun shubuha zuwa amintattun tsarin samarwa. Na tsara gine-ginen da ke bayan React, Angular, .NET, Node.js, Java, C#, Go, da aikace-aikacen SQL: bayyanannun iyakokin sabis, samfuran bayanai masu dorewa, amintattun hanyoyin samun dama, da \u0199ungiyoyin hanyoyin isar da sako na iya aiki tare da amincewa.","descriptionB":"Aikina yana ha\u0257a shawarar injiniya zuwa sakamakon kasuwanci. Daga SaaS mai \u0199ididdige gine-gine wanda ke juya bayanan ma\u0199unsar bayanai zuwa shawarwarin shirye-shiryen abokin ciniki zuwa dandamalin yanar gizo masu samar da kudaden shiga, Ina gina software a kusa da ayyukan aiki, ha\u0257ari, da auna ma\'auni mai mahimmanci ga mutanen da ke amfani da shi.","portfolio_button":"Fayil nawa","contact_button":"Tuntube Ni","about_button":"Akai na"},"about":{"title":"Akai na","personal_summary":{"title":"Takaitaccen Bayani","text":"Ni babban injiniya ne mai cikakken tari wanda ke zaune a Orlando, FL wanda ya mallaki hanya daga matsalar samfur zuwa sakamakon samarwa. Ina yin za\u0253in fasaha a cikin sabis na tsarin: NET da Tsarin Tsarin Ha\u0253akawa lokacin da \u0199a\u0199\u0199arfan tsarin yanki da abin dagewa za\'a iya gwadawa; Angular ko Amsa lokacin da hadaddun ayyukan aiki suna bu\u0199atar dubawa mai kulawa; Node.js ko Go lokacin da API, ha\u0257in kai, ko babban aiki kayan aiki yana bu\u0199atar lokacin aiki mai mahimmanci. A duk fa\u0257in samfuran SaaS, ayyukan aiki na ciki, da dandamali masu fuskantar abokin ciniki, Ina jagora tare da fayyace fage, \u0199ira mai aminci da juriya, gwajin sarrafa kansa, da ayyukan isarwa wa\u0257anda Taimakawa \u0199ungiyoyi don jigilar software mai mahimmanci ba tare da barin bashin aiki a baya ba."},"professional_experience":{"title":"Kwarewar \u0198wararru","entries":[{"jobtitle":"Babban Injiniya Software","where":"Zane Mai Mu\'amala","date":"2025 - Yanzu"},{"jobtitle":"Injiniyan Software","where":"Orion180 Insurance","date":"2024-2025"},{"jobtitle":"Injiniyan Software","where":"SupremeMC","date":"2020-2024"},{"jobtitle":"Injiniyan Software","where":"Hanzarta Koyo","date":"2023"},{"jobtitle":"Jagorar Injiniya Software (Shirin Dalibai)","where":"Shirin GDI na Jami\'ar Clemson","date":"2021-2022"},{"jobtitle":"Mai Kula da Tebura","where":"Jami\'ar Clemson","date":"2021-2022"}]},"technical_skills":{"title":"\u0198warewar Fasaha","header1":"Harsunan Shirye-shiryen","header2":"Tsarin Mulki & Dakunan karatu","header3":"Kayan aiki & Fasaha"},"services":{"title":"Ayyukana","entries":[{"title":"Injiniya Cikakkun Tari","text":"Ina jagorantar isar da samfur na \u0199arshe-zuwa-\u0199arshen: fassara ayyukan kasuwanci zuwa iyakokin tsarin, \u0199irar bayanai, APIs, da musaya, sannan \u0257aukar aikin ta hanyar gwaji, turawa, da maimaitawa. Manufar ita ce software da \u0199ungiya za ta iya ha\u0253akawa da aiki, ba tarin hotunan allo ba."},{"title":"Samfura & Tsarin Gine-gine","text":"Na za\u0253i dandamali da alamu dangane da matsalar: sabis na .NET mai layi don wuraren kasuwanci, aikace-aikacen Angular ko React mai sarrafa kayan aiki don hadaddun ayyuka, ala\u0199a samfuran bayanai don ayyukan aiki masu lissafin lissafi, da ha\u0257in kai da aka tsara tare da yanayin gazawa, ikon samun dama, da kiyayewa a hankali."},{"title":"Bayarwa-Shirya Bayarwa","text":"Ina ginawa tare da gaskiyar bayan \u0199addamar da ra\'ayi: sirrin da aka kiyaye su daga sarrafa tushe, \u0199ayyadaddun hanyoyin \u0199aura na bayanai, izini na tushen rawar, inganci a iyakokin tsarin, gwaje-gwaje na atomatik, wayar da kan jama\'a ta CI/CD, da kuma lura da aiki. Wa\u0257annan su ne cikakkun bayanai wa\u0257anda ke juya samfuri zuwa software mai dogaro."}]}},"portfolio":{"title":"Fayil","filter_by":"Tace Portfolio Ta:","entries":{"biblioteca":{"title":"Biblioteca JSON","text":"Bututun da ke tushen Python wanda ke juya tushen tushen abun ciki guda \u0257aya zuwa babban fayil mai isa ga duniya. Yana sarrafa bayanan fassarar azaman tsarin da za\'a iya kiyayewa maimakon kwafin shafi da hannu, ba da damar rukunin yanar gizon ya yi \u0199ima a cikin harsuna sama da 100 kuma yana sa duniya ta kai matsayin kofi. iya aiki maimakon fasalin lokaci \u0257aya.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Ha\u0257a Hu\u0257u","text":"Babban dangi na aiwatar da fiye da 50+ na wasan Connect Four. Wannan aikin ya \u0199unshi aiwatarwa a cikin harsunan shirye-shirye sama da 30, gami da Java, C++, Python, JavaScript, da \u0199ari. Bugu da \u0199ari, ya ha\u0257a da fiye da 20+ tsari daban-daban ko wasu tsari, gami da React.js, Ruby on Rails, ASP.NET, da \u0199ari.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"App na Kayan Abinci","text":"Cikakken kayan aikin NET 9 Blazor Server wanda ke nuna tsarin gine-ginen baya na niyya don tafiyar da kasuwanci. Rarraba mai sarrafawa/sabis/maajiyar tana kiyaye dokokin aikace-aikace, samun damar bayanai, da gabatarwa daban-daban; Tsarin Tsarin Halittu Core yana ba da dorewa mai dorewa; da kuma babban \u0257akin gwaji yana kare \u0257abi\'a yayin da samfurin ke tasowa.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Interop Project","text":"Ma\'anar ma\'amala tsakanin harshen giciye wanda ya \u0199unshi harsunan shirye-shirye 15 da tsarin aiwatarwa 18. Aikin yana bincika iyakar inda tsarin yakan zama mai rauni: kwangilar tsari, musayar bayanai, halayen lokacin aiki, da hanyoyin ha\u0257in kai mai maimaitawa. Yana nuna tunanin tsarin da ake bu\u0199ata lokacin da samfur ya fi girma fiye da tari \u0257aya.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Rijistar kayayyaki","text":"Cikakken POS mai cike da kayan aiki da kayan aiki da aka gina tare da Angular 17+ da Node.js. Yana misalta abubuwan da ke damun tsarin aiki na tsarin B2B: ingantattun masu amfani, sarrafa tushen rawar aiki, daidaiton \u0199ira, da kwararar biyan ku\u0257i na izgili. An tsara aikin a kusa da ainihin aikin da \u0199ungiyar rajista ke yi, ba kawai kasida na fasalulluka ba.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"JSON & YAML Auto Formater","text":"JSON na tushen burauza da ingantaccen kayan aikin YAML da aka gina a cikin Go kuma an ha\u0257a su zuwa WebAssembly. Matsar da injin fasinja zuwa WASM yana sa hul\u0257ar ta kasance mai amsawa kuma ta gida ga mai binciken yayin da ake amfani da fasinja na gaske don kama shigar da ba daidai ba. Misali ne da aka mayar da hankali na zabar tsarin gine-ginen lokacin aiki don aiki, \u0257aukakawa, da amanar mai amfani.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Injin Takeoff","text":"Gine-gine mai \u0199ididdigewa SaaS da aka gina a kusa da farashi mai tsada, aikin \u0257an kwangila mai kuskuren kuskure. Samfurin React + Express yana shigar da bayanan CSV da Excel, taswirorin ginshi\u0199ai marasa daidaituwa a cikin \u0199irar yanki mai amfani, \u0199ididdige tono rami da juzu\'in aikin \u0199asa, wa\u0199a da aiki da alama, kuma yana samar da shirye-shiryen abokin ciniki na PDF da shawarwarin Kalma. Wannan cikakken aikin injiniya ne na rayuwar samfur: tantance bayanai, \u0199a\'idodin lissafin, gogewar aikin mai aiki, da abubuwan da za\'a iya samarwa wa\u0257anda ke taimakawa kasuwanci don matsawa daga danyen bayanai zuwa tayi.","link":"https://takeoffengine.com"},"minecraft_json_generator":{"title":"Minecraft JSON Generator","text":"JSON janareta mai nauyi wanda aka gina a cikin Python don albarkatun Minecraft & fakitin bayanai. Ana amfani da wannan aikin don samar da fayilolin JSON don mods na Minecraft, gami da abubuwan al\'ada, tubalan, da mahalli. Yana da amfani sosai don ba kawai \u0199ir\u0199irar fakitin bayanai na al\'ada ba, amma don mods kuma ta hanyar fasalin canza sunan na zamani.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"Kwarewar Ilimi ta","text":"Tare da ayyukana na sirri, na kuma sami \u0199warewa da yawa daga gogewar ilimi. Danna nan don duba bayanin martaba na LinkedIn don \u0199arin bayani.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"Kwarewar \u0198wararru ta","text":"Shekaru shida da \u0199ari na \u0199warewar injiniyan \u0199wararru a cikin \u0199ungiyoyin samfura, dandamalin kasuwanci, da software na fuskantar abokin ciniki. Ayyukana sun ha\u0257a da gina matakan aikace-aikacen da za\'a iya kiyayewa, ha\u0257in gwiwa a duk fannonin bayarwa, da yanke shawarar fasaha tare da tsarin rayuwar samfur, aiki kasada, da kuma mallakar dogon lokaci a gani.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Yanar Gizon Fayil na Patrick Goodwin","text":"Fayil \u0257in amsa mai ra\'ayin samarwa wanda ke kula da isa da isa ga duniya azaman bu\u0199atun injiniya. Ya ha\u0257a da bututun fassarar da za a iya kiyayewa don harsuna 100+, kayan aikin mu\'amala da WebAssembly ke goyan baya, \u0199irar UI mai amsawa da samun dama, da tsarin gine-ginen aiki. an tsara don girma yayin da ake jigilar sabon aiki.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Patrick\'s Lua Script Library","text":"Laburare mai fa\'ida na rubutun Lua don tunani na gaba. Ana amfani da wannan \u0257akin karatu don sarrafa ayyuka a cikin rubutun Lua, wanda zai iya zuwa da amfani don ayyuka masu bu\u0199ata, saboda Lua yawanci yaren rubutu ne mai sauri fiye da Python da Ruby.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Patrick\'s Microsoft Excel Rubutun Rubutun Rubutun (VBA)","text":"Laburare mai amfani na rubutun VBA don Microsoft Excel. Ana amfani da wannan \u0257akin karatu don sarrafa ayyuka a cikin ma\u0199unsar bayanai na Excel.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Patrick\'s Neovim Config","text":"Tsari na Neovim na sirri. Ana amfani da wannan aikin don saita Neovim ga abin da nake so, gami da ma\u0253alli na al\'ada, jigogi, da plugins. Ana amfani da wannan aikin don sanya Neovim ya fi dacewa da mai amfani da inganci don amfanin kaina.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Patrick\'s Map Generator","text":"Kayan aikin ba da rahoto na geospatial Python wanda aka gina tare da GeoPandas da Matplotlib don samar da gundumar Amurka da taswirar jihohi. Yana juya bayanan yanki zuwa kayan tarihi masu iya karantawa, yana nuna tunanin bututun bayanai: za\u0253i \u0257akunan \u0257akunan karatu da suka dace, daidaita abubuwan da aka shigar, da samar da abubuwan da zasu iya haifar da. goyi bayan yanke shawara.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Patrick\'s PowerShell Script Library","text":"Laburare mai fa\'ida na rubutun PowerShell don tunani na gaba. Mai amfani tare da fasalin rubutun bayanan $, Na sami wannan yana taimakawa sosai don sarrafa ayyuka daga tashar Windows, saboda ni mai yawan amfani da Windows OS ne.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Patrick\'s Ruby Script Library","text":"Laburare mai amfani na rubutun Ruby don tunani na gaba. Yana da amfani ga tunanin ci gaban Ruby akan Rails na gaba.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"PDF Skills Builder","text":"Tsarin aiki na tsara daftarin aiki wanda aka gina tare da Python, Pdfkit, Jinja2, HTML, da bayanan JSON da aka tsara. Yana raba bayanan da za a sake amfani da su daga samfuran gabatarwa don samar da ke\u0253a\u0253\u0253en abubuwan dawo da PDF akai-akai, tsari mai amfani don rage aikin hannu da yin takaddun kasuwanci. maimaituwa.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Rijandel Encryption Project","text":"Saitin kwatancen aiwatarwa 10+ Rijndael a cikin bambance-bambancen 128-, 192-, da 256-bit. Sake aiwatar da algorithm mai hankali na tsaro a cikin harsunan horo ne mai horo a cikin takamaiman \u0199ayyadaddun bayanai, halayen da za a iya gwadawa, da iyakan iya \u0257aukar matakin matakin harshe, duk ilhami masu amfani ga tsarin da ke sarrafa bayanai masu mahimmanci.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"SupremeMC Minecraft Mod","text":"Mod \u0257in Minecraft wanda ke \u0199ara kayan aikin al\'ada, sulke, \u0199ungiyoyin jama\'a, tubalan, girma, da \u0199ari masu yawa ga wasan. Gina tare da nau\'ikan Java 8-17 don za\u0253i nau\'ikan Minecraft tsakanin 1.16 da 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"Tiger Programming Language","text":"Yaren tsara shirye-shirye na al\'ada da mai fassara da aka gina a cikin Go don bincika \u0199irar lokacin aiki na harshe, halayen aiwatarwa, da cinikin aiki. \u0198ir\u0199irar shi zuwa WebAssembly da ha\u0257a shi a cikin fayil \u0257in yana haifar da ha\u0199i\u0199a, samfurin samfurin da ba a iya gani ba don aikin injiniya na matakin tsarin maimakon barin aikin a matsayin ma\'ajiya-kawai gwaji.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Tiger Tailgating Pros Yanar Gizo","text":"Gidan yanar gizon React da aka bayar don kasuwanci na Clemson, SC. Aikin yana fassara hadayar \u0199aramin kasuwanci zuwa \u0199ayyadadden tafiyar abokin ciniki da kasancewar gidan yanar gizo mai dogaro, yin amfani da tunanin samfur don taimakawa \u0199ungiyar gaske ta canza sha\'awa. cikin tambayoyi da kudaden shiga.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Aikin Turing Machine","text":"Iyalin sama da 30+ aiwatar da Injin Turing. An yi amfani da shi don nuna cikar turing don harsunan shirye-shirye daban-daban don bincike, musamman don Harshen Shirye-shiryen Tiger.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"Tiger Programming Language"},"contact":{"title":"Tuntube Ni","header":"Bayanin hulda","email":"pattygsocials@gmail.com","description":"Ina amsa tambayoyi daga imel da sa\u0199onnin LinkedIn. Zan sake kira idan an bayar da lamba ta ta hanyar ci gaba ko akasin haka, kodayake na fi son in kiyaye lambar waya ta a sirri."},"formatter":{"title":"JSON & YAML Linter","description":"Kayan aiki mai inganci na tushen burauza wanda ke ingantawa da tsara JSON da YAML ta amfani da injin Go da aka harhada zuwa WebAssembly. Gine-ginen yana ci gaba da \u0253arna kusa da mai amfani don amsa mai sauri, masu zaman kansu yayin aiwatar da ainihin \u0199a\'idodin syntax a iyakar bayanai. \u0198a\u0199\u0199arfan misali ne na \u0199ir\u0199ira ingantaccen aiki na mai ha\u0253akawa a kusa da daidaito, aiki, da amana.","more_info1":"Don \u0199arin bayani, koma zuwa README a cikin","more_info2":"Ma\'ajiyar Tsarin Tsarin JSON/YAML.","format_as":"Tsara Kamar:","auto_detect":"Gano atomatik","format":"Lint & Tsarin","valid_json":"\u2713 Inganci JSON","valid_yaml":"\u2713 Ingantaccen YAML","invalid_json":"JSON mara aiki","invalid_yaml":"YAML mara inganci","empty_input":"Da fatan za a shigar da wasu JSON ko YAML zuwa lint.","too_large":"Shigarwa yayi girma sosai (matsakaicin 1MB da aka yarda).","fixed_yaml_spacing":"\u26a0 YAML yana da tazara/shiga mara inganci amma an daidaita shi ta atomatik kuma an tsara shi.","loading":"Ana loda mai tsarawa...","waiting_for_input":"Ana jiran shigarwa...","load_failed":"An kasa loda mai tsarawa.","output":"Fitowa:","input_code":"Shigarwa","json_examples":"Misalin JSON","yaml_examples":"Misalin YAML"},"tiger":{"title":"Harshen Tiger","description":"Tiger yaren tsara shirye-shirye ne na al\'ada da mai fassarar Go wanda aka gina don bincika gine-ginen lokacin aiki, nazarin harshe, da cinikin aiki. \u0198ir\u0199irar mai fassara zuwa WebAssembly yana juya cewa tsarin yana aiki zuwa samfurin ma\'amala, tushen burauzar: masu amfani zasu iya aiwatar da shirye-shirye kai tsaye yayin da lokacin aiki ya kasance mai \u0257aukar nauyi. kuma ke\u0253e daga aikace-aikacen mai watsa shiri.","more_info1":"Don \u0199arin bayani, koma zuwa README a cikin","more_info2":"Tiger Programming Language GitHub Repository.","select_engine":"Za\u0253i Injin:","tiger_code":"Lambar Tiger:","run_tiger":"Run Tiger","output":"Fitowa:"},"tab":{"title":"Patrick Goodwin","description":"Babban injiniya mai cikakken tari tare da shekaru 6+ na gwaninta \u0199irar samfuran SaaS, tsarin samarwa, da software na samar da kudaden shiga."},"copy":{"text":"Kwafi","copied":"Kwafi!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"Bi ni"},"languages":{"title":"Mai Fassarar Fayil","description":"Gano yadda babban fayil na ke samun dama ga ba\u0199i daga ko\'ina cikin duniya tare da tallafi sama da harsuna 100.","global_accessibility":{"title":"Samun damar Duniya","description":"Fayil nawa yana samuwa a cikin harsuna sama da {count}, yana mai da shi isa ga ba\u0199i daga ko\'ina cikin duniya. Wannan tsarin yaruka da yawa yana nuna himmata ga ha\u0257a kai da isar da sa\u0199on ci gaban software.","stats":{"languages_supported":"Harsuna Masu Tallafawa","countries_represented":"Kasashen da ke wakiltar","continents_covered":"Nahiyoyi An Rufe"}},"features":{"title":"Siffofin","items":[{"title":"Fassara na ainihi:","description":"Canja harsuna nan take tare da mai za\u0253in harshe"},{"title":"Harshen URL:","description":"Ana adana abubuwan za\u0253in harshe a cikin URL"},{"title":"Taimakon Rubutun \u0198asa:","description":"Yadda ake fassara rubutun kamar Larabci, Sinanci, Hindi, da \u0199ari"},{"title":"Hankalin al\'adu:","description":"Fassara suna la\'akari da mahallin al\'adu, ba kawai ma\'anoni na zahiri ba"},{"title":"Ingantaccen SEO:","description":"An inganta kowane bambance-bambancen harshe don injunan bincike"}]},"world_map":{"title":"Taswirar Duniya Mai Ma\'amala","description":"Yi shawagi a kan \u0199asa akan taswira don ganin harsunan da suke da tallafi:","languages_label":"Harsuna","legend":{"supported":"Harsuna Masu Tallafawa","not_supported":"Babu Tallafin Harshe"},"zoom_controls":{"zoom_in":"Zu\u0199owa","zoom_out":"Zu\u0199owa waje","reset":"Sake saita Duban"}},"supported_languages":{"title":"Harsuna masu goyan baya"},"interactive_country_map":{"title":"Taswirar \u0199asa mai hul\u0257a","description":"Yi shawagi a kan \u0199asashen da ke \u0199asa don ganin harsunan da suke da tallafi:","language_count":{"single":"harshe","multiple":"harsuna"}},"tooltips":{"no_language_support":"Babu tallafin harshe"}},"logotext":"PATRICK"}')}}]);